mapper.select:
    SELECT * FROM ha_interaction
WHERE owner_key = #{ownerKey} AND interaction_type = 'APPROVAL' AND session_id = #{sessionId} AND turn_id = #{turnId} AND status = #{status}
ORDER BY created_at, interaction_id

mapper.update:
    UPDATE ha_interaction
SET status = #{status}, response_json = #{responseJson}, resolved_at = #{resolvedAt}, updated_at = #{updatedAt}, version = version + 1
WHERE owner_key = #{ownerKey} AND interaction_type = 'APPROVAL' AND interaction_id = #{interactionId} AND status = #{status2} AND version = #{version}
